/// The autohint stem for a PostScript name; 0 when the registry has none.
[[nodiscard]] inline std::uint16_t autohint_stem(std::string_view ps_name) noexcept {
    const auto* b = std::begin(autohint_stems);
    const auto* e = std::end(autohint_stems);
    const auto* it = std::lower_bound(b, e, ps_name, [](const StemEntry& s, std::string_view n) { return s.name < n; });
    return it != e && it->name == ps_name ? it->stem : 0;
}

